import java.util.*;

class Solution {
    public int findMaximum(int[] nums) {
        int index = 0;
        int maxElement = nums[0];

        while (index < nums.length) {
            if (nums[index] > maxElement) {
                maxElement = nums[index];
            }
            index++;
        }

        return maxElement;
    }
}
